237	/// Return the existing or a new name for a Value.
238	StringRef CodeEmitter::getOrCreateName(Value val)
239	{
240	    if (!valueMapper.count(val)) {
241	        std::string name = nameStack.getNameForEmission(val);
242	        if (auto loc = val.getLoc()->findInstanceOf<NameLoc>())
243	            name = formatv("{0}_{1}", name, loc.getName().getValue()).str();
244	        valueMapper.insert(val, name);
