257	bool CodeEmitter::shouldMapToUnsigned(IntegerType::SignednessSemantics val)
258	{
259	    switch (val) {
260	        case IntegerType::Signless:
261	        case IntegerType::Signed:
262	            return false;
263	        case IntegerType::Unsigned:
264	            return true;
265	    }
266	    llvm_unreachable("Unexpected IntegerType::SignednessSemantics");
267	}
