273	void CodeEmitter::printInt(const APInt& value, bool isUnsigned)
274	{
275	    if (value.getBitWidth() == 1) {
276	        if (value.getBoolValue())
277	            os << "true";
278	        else
279	            os << "false";
280	    } else {
281	        constexpr uint32_t toStringLen = 10;
282	        SmallString<smallStringLength> strValue;
283	        value.toString(strValue, toStringLen, !isUnsigned, false);
284	        os << strValue;
285	    }
286	}
287	
288	void CodeEmitter::printFloat(const APFloat& value)
289	{
290	    if (value.isFinite()) {
291	        SmallString<smallStringLength> strValue;
292	        // Use default values of toString except don't truncate zeros.
293	        value.toString(strValue, 0, 0, false);
294	        switch (llvm::APFloatBase::SemanticsToEnum(value.getSemantics())) {
295	            case llvm::APFloatBase::S_IEEEsingle:
296	                os << "(float)";
297	                break;
298	            case llvm::APFloatBase::S_IEEEdouble:
299	                os << "(double)";
300	                break;
301	            default:
302	                break;
303	        };
304	        os << strValue;
305	    } else if (value.isNaN()) {
306	        os << "(0.f / 0.f) /* nan */";
307	    } else if (value.isInfinity()) {
308	        if (value.isNegative())
309	            os << "-";
310	        os << "__builtin_inff()";
311	    }
312	}
