323	LogicalResult CodeEmitter::emitOperands(Operation& op)
324	{
325	    auto emitOperand = [&](Value result) -> LogicalResult {
326	        if (!hasValueInScope(result))
327	            return op.emitOpError() << "operand value not in scope";
328	        os << getOrCreateName(result);
329	        return success();
330	    };
331	    return interleaveCommaWithError(op.getOperands(), os, emitOperand);
332	}
