334	LogicalResult CodeEmitter::emitVariableDeclaration(OpResult opResult, bool trailingSemicolon)
335	{
336	    if (hasValueInScope(opResult)) {
337	        return opResult.getDefiningOp()->emitError("result variable for the operation already declared");
338	    }
339	    if (failed(emitType(opResult.getOwner()->getLoc(), opResult.getType())))
340	        return failure();
341	    os << " " << getOrCreateName(opResult);
342	    if (trailingSemicolon)
343	        os << ";\n";
344	    return success();
345	}
346	
347	LogicalResult CodeEmitter::emitAssignPrefix(Operation& op)
348	{
349	    switch (op.getNumResults()) {
350	        case 0:
351	            break;
352	        case 1: {
353	            OpResult result = op.getResult(0);
354	            if (failed(emitVariableDeclaration(result, /*trailingSemicolon=*/false)))
355	                return failure();
356	            os << " = ";
357	            break;
358	        }
359	        default:
360	            llvm_unreachable("emission for multiple results is not implemented");
361	    }
362	    return success();
363	}
