365	LogicalResult CodeEmitter::emitLabel(Block& block)
366	{
367	    if (!hasBlockLabel(block))
368	        return block.getParentOp()->emitError("label for block not found");
369	    // Add feature in `raw_indented_ostream` to ignore indent for block
370	    // label instead of using `getOStream`.
371	    os.getOStream() << getOrCreateName(block) << ":\n";
372	    return success();
373	}
