410	LogicalResult CodeEmitter::emitTensorType(Location loc, Type type, bool /*emitAsUnsigned*/)
411	{
412	    auto tensorType = dyn_cast<TensorType>(type);
413	    if (!tensorType.hasRank())
414	        return emitError(loc, "cannot emit unranked tensor type");
415	    if (!tensorType.hasStaticShape())
416	        return emitError(loc, "cannot emit tensor type with non static shape");
417	    os << "Tensor<";
418	    if (failed(emitType(loc, tensorType.getElementType())))
419	        return failure();
420	    auto shape = tensorType.getShape();
421	    for (auto dimSize : shape) {
422	        os << ", ";
423	        os << dimSize;
424	    }
425	    os << ">";
426	    return success();
427	}
