673	LogicalResult CodeEmitter::emitAscMatmulTypeTemplate(Location loc, Type type, bool /*emitAsUnsigned*/)
674	{
675	    auto pType = dyn_cast<ascendc::MatmulType>(type);
676	    emitMatmulConfig(os, pType.getMatmulConfig());
677	    os << "matmul::Matmul";
678	    os << "<matmul::MatmulType<";
679	    emitTPosition(os, pType.getSrcAPosition());
680	    os << ", ";
681	    emitCubeFormat(os, pType.getCubeFormatA());
682	    os << ", ";
683	    if (failed(emitType(loc, pType.getTypeA())))
684	        return failure();
685	    os << ", ";
686	    if (pType.getIsTransA())
687	        os << "true, ";
688	    else
689	        os << "false, ";
690	    emitLayoutMode(os, pType.getLayoutModeA());
691	    os << ">, matmul::MatmulType<";
692	    emitTPosition(os, pType.getSrcBPosition());
693	    os << ", ";
694	    emitCubeFormat(os, pType.getCubeFormatB());
695	    os << ", ";
696	    if (failed(emitType(loc, pType.getTypeB())))
697	        return failure();
698	    os << ", ";
699	    if (pType.getIsTransB())
700	        os << "true, ";
701	    else
702	        os << "false, ";
703	    emitLayoutMode(os, pType.getLayoutModeB());
704	    os << ">, matmul::MatmulType<";
705	    emitTPosition(os, pType.getSrcCPosition());
706	    os << ", ";
707	    emitCubeFormat(os, pType.getCubeFormatC());
708	    os << ", ";
709	    if (failed(emitType(loc, pType.getTypeC())))
710	        return failure();
711	    os << ", ";
712	    if (pType.getIsTransC())
713	        os << "true, ";
714	    else
715	        os << "false, ";
716	    emitLayoutMode(os, pType.getLayoutModeC());
717	    os << ">, matmul::MatmulType<";
718	    emitTPosition(os, pType.getSrcBiasPosition());
719	    os << ", ";
720	    emitCubeFormat(os, pType.getCubeFormatBias());
721	    os << ", ";
722	    if (failed(emitType(loc, pType.getTypeBias())))
723	        return failure();
724	    os << ">, ";
725	    os << "CFG";
726	    os << ">";
727	    return success();
728	}
