730	LogicalResult CodeEmitter::emitAscMatmulSimplifiedTemplate(Location loc, Type type, bool /*emitAsUnsigned*/)
731	{
732	    auto pType = dyn_cast<ascendc::MatmulType>(type);
733	    os << "<matmul::MatmulType<";
734	    emitTPosition(os, pType.getSrcAPosition());
735	    os << ", ";
736	    emitCubeFormat(os, pType.getCubeFormatA());
737	    os << ", ";
738	    if (failed(emitType(loc, pType.getTypeA())))
739	        return failure();
740	    os << ", ";
741	    if (pType.getIsTransA())
742	        os << "true, ";
743	    else
744	        os << "false, ";
745	    emitLayoutMode(os, pType.getLayoutModeA());
746	    os << ">, matmul::MatmulType<";
747	    emitTPosition(os, pType.getSrcBPosition());
748	    os << ", ";
749	    emitCubeFormat(os, pType.getCubeFormatB());
750	    os << ", ";
751	    if (failed(emitType(loc, pType.getTypeB())))
752	        return failure();
753	    os << ", ";
754	    if (pType.getIsTransB())
755	        os << "true, ";
756	    else
757	        os << "false, ";
758	    emitLayoutMode(os, pType.getLayoutModeB());
759	    os << ">, matmul::MatmulType<";
760	    emitTPosition(os, pType.getSrcCPosition());
761	    os << ", ";
762	    emitCubeFormat(os, pType.getCubeFormatC());
763	    os << ", ";
764	    if (failed(emitType(loc, pType.getTypeC())))
765	        return failure();
766	    os << ", ";
767	    if (pType.getIsTransC())
768	        os << "true, ";
769	    else
770	        os << "false, ";
771	    emitLayoutMode(os, pType.getLayoutModeC());
772	    os << ">, matmul::MatmulType<";
773	    emitTPosition(os, pType.getSrcBiasPosition());
774	    os << ", ";
775	    emitCubeFormat(os, pType.getCubeFormatBias());
776	    os << ", ";
777	    if (failed(emitType(loc, pType.getTypeBias())))
778	        return failure();
779	    os << ">>";
780	    return success();
781	}
782	
783	LogicalResult CodeEmitter::emitAscMatmulType(Location loc, Type type, bool emitAsUnsigned)
784	{
785	    return emitAscMatmulTypeTemplate(loc, type, emitAsUnsigned);
786	}
787	
788	LogicalResult CodeEmitter::emitIntegerType(IntegerType& iType, Location loc, Type type, bool emitAsUnsigned)
789	{
790	    switch (iType.getWidth()) {
791	        case dtypeBitWidth1:
792	            return (os << "bool"), success();
793	        case dtypeBitWidth8:
794	        case dtypeBitWidth16:
795	        case dtypeBitWidth32:
796	        case dtypeBitWidth64:
797	            if (shouldMapToUnsigned(iType.getSignedness()) || emitAsUnsigned)
798	                return (os << "uint" << iType.getWidth() << "_t"), success();
799	            else
800	                return (os << "int" << iType.getWidth() << "_t"), success();
801	        default:
802	            return emitError(loc, "cannot emit integer type ") << type;
803	    }
804	}
805	
806	LogicalResult CodeEmitter::emitFloatType(FloatType& fType, Location loc, Type type, bool /*emitAsUnsigned*/)
807	{
808	    switch (fType.getWidth()) {
809	        case dtypeBitWidth16:
810	            return (os << "half"), success();
811	        case dtypeBitWidth32:
812	            return (os << "float"), success();
813	        case dtypeBitWidth64:
814	            return (os << "double"), success();
815	        default:
816	            return emitError(loc, "cannot emit float type ") << type;
817	    }
818	}
819	
820	LogicalResult CodeEmitter::emitBaseMemRefType(BaseMemRefType& pType, Location loc, Type /*type*/, bool emitAsUnsigned)
821	{
822	    if (auto attr = pType.getMemorySpace()) {
823	        auto value = static_cast<uint8_t>(cast<IntegerAttr>(attr).getInt());
824	        if (auto addrSpace = ascendc::symbolizeAddressSpace(value))
825	            emitAddressSpace(addrSpace.value());
826	        else
827	            return failure();
828	    }
829	    if (failed(emitType(loc, pType.getElementType(), emitAsUnsigned)))
830	        return failure();
831	    os << "*";
832	    return success();
833	}
834	
835	LogicalResult CodeEmitter::emitType(Location loc, Type type, bool emitAsUnsigned)
836	{
837	    auto it = emitTypeMapper.find(type.getTypeID());
838	    if (it != emitTypeMapper.end()) {
839	        return it->second(loc, type, emitAsUnsigned);
840	    }
841	    if (auto iType = dyn_cast<IntegerType>(type)) {
842	        return emitIntegerType(iType, loc, type, emitAsUnsigned);
843	    }
844	    if (auto fType = dyn_cast<FloatType>(type)) {
845	        return emitFloatType(fType, loc, type, emitAsUnsigned);
846	    }
847	    if (auto pType = dyn_cast<BaseMemRefType>(type)) {
848	        return emitBaseMemRefType(pType, loc, type, emitAsUnsigned);
849	    }
850	
851	#define GEN_EMITTER
852	#include "ascir/API/Types.h.inc"
853	    return emitError(loc, "cannot emit type ") << type;
854	}
855	
856	LogicalResult CodeEmitter::emitAscPyStructType(Location /*loc*/, Type type, bool /*emitAsUnsigned*/)
857	{
858	    auto pType = dyn_cast<emitasc::PyStructType>(type);
859	    os << pType.getNameAttr().getValue();
860	    return success();
861	}
