863	LogicalResult CodeEmitter::emitAscDataCopyPadExtParamsType(Location loc, Type type, bool /*emitAsUnsigned*/)
864	{
865	    auto ldType = dyn_cast<ascendc::DataCopyPadExtParamsType>(type);
866	    os << ascNamespace << "::DataCopyPadExtParams<";
867	    if (failed(emitType(loc, ldType.getElementType())))
868	        return failure();
869	    os << '>';
870	    return success();
871	}
872	
873	LogicalResult CodeEmitter::emitAscMrgSortSrcListType(Location loc, Type type, bool /*emitAsUnsigned*/)
874	{
875	    auto ldType = dyn_cast<ascendc::MrgSortSrcListType>(type);
876	    os << ascNamespace << "::MrgSortSrcList<";
877	    if (failed(emitType(loc, ldType.getElementType())))
878	        return failure();
879	    os << '>';
