883	LogicalResult CodeEmitter::emitTypes(Location loc, ArrayRef<Type> types)
884	{
885	    switch (types.size()) {
886	        case 0:
887	            os << "void";
888	            return success();
889	        case dtypeBitWidth1:
890	            return emitType(loc, types.front());
891	        default:
892	            llvm_unreachable("unsupported emission of types array");
893	    }
