LogicalResult CodeEmitter::emitTypes(Location loc, ArrayRef<Type> types)
{
    switch (types.size()) {
        case 0:
            os << "void";
            return success();
        case dtypeBitWidth1:
            return emitType(loc, types.front());
        default:
            llvm_unreachable("unsupported emission of types array");
    }
}

